using KaraokeManager.BUS;using System.Data;
namespace KaraokeManager.GUI;
public sealed class MainForm:Form
{
 readonly KaraokeService svc=new();readonly TabControl tabs=new(){Dock=DockStyle.Fill};readonly FlowLayoutPanel roomGrid=new(){Dock=DockStyle.Fill,AutoScroll=true,Padding=new Padding(14)};readonly DataGridView serviceGrid=Grid(),orderGrid=Grid(),reportGrid=Grid(),detailGrid=Grid(),serviceOrderGrid=Grid();readonly TextBox serviceName=new(){Width=210},servicePrice=new(){Width=100},serviceStock=new(){Width=80};readonly ComboBox roomChoice=new(){Width=170,DropDownStyle=ComboBoxStyle.DropDownList},serviceChoice=new(){Width=200,DropDownStyle=ComboBoxStyle.DropDownList};readonly NumericUpDown qty=new(){Minimum=1,Maximum=999,Value=1,Width=75};readonly Label currentBill=new(){AutoSize=true,Font=new Font("Segoe UI",12,FontStyle.Bold),ForeColor=Color.DarkSlateBlue};int? serviceId,selectedRoom;DataTable? services,serviceTable;int? billId;
 public MainForm(){Text="KaraokeHub | Quản lý phòng hát & dịch vụ";Width=1320;Height=850;StartPosition=FormStartPosition.CenterScreen;Font=new Font("Segoe UI",10);BackColor=Color.FromArgb(246,248,250);BuildRooms();BuildServices();BuildOrders();BuildReports();Controls.Add(tabs);Shown+=(_,_)=>RefreshAll();}
 static DataGridView Grid()=>new(){Dock=DockStyle.Fill,ReadOnly=true,AllowUserToAddRows=false,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill,SelectionMode=DataGridViewSelectionMode.FullRowSelect,BackgroundColor=Color.White,BorderStyle=BorderStyle.None};TabPage Page(string s){var p=new TabPage(s){Padding=new Padding(12),BackColor=Color.FromArgb(246,248,250)};tabs.TabPages.Add(p);return p;}static Label L(string s)=>new(){Text=s,AutoSize=true,Margin=new Padding(5,9,1,2)};static Button B(string s,EventHandler e){var b=new Button{Text=s,AutoSize=true,Height=34,Margin=new Padding(3),BackColor=Color.White};b.Click+=e;return b;}static FlowLayoutPanel Bar(int h)=>new(){Dock=DockStyle.Top,Height=h,Padding=new Padding(2,5,2,3),WrapContents=true};
 void BuildRooms(){var p=Page("Sơ đồ phòng");var head=new Panel{Dock=DockStyle.Top,Height=116};head.Controls.Add(new Label{Text="KARAOKEHUB  |  SƠ ĐỒ PHÒNG HÁT",Font=new Font("Segoe UI",22,FontStyle.Bold),ForeColor=Color.FromArgb(30,64,114),Location=new Point(10,5),AutoSize=true});head.Controls.Add(new Label{Name="roomStats",Text="Phòng Trống màu xanh  •  Đang hát màu đỏ",Font=new Font("Segoe UI",12),Location=new Point(14,48),AutoSize=true});var bar=Bar(48);bar.Controls.Add(B("Làm mới sơ đồ",(_,_)=>LoadRooms()));head.Controls.Add(bar);p.Controls.Add(roomGrid);p.Controls.Add(head);}
 void BuildServices(){var p=Page("Danh mục dịch vụ");var top=Bar(74);top.Controls.AddRange(new Control[]{L("Tên dịch vụ"),serviceName,L("Đơn giá"),servicePrice,L("Tồn kho"),serviceStock,B("Thêm / cập nhật",(_,_)=>SaveService()),B("Làm mới",(_,_)=>LoadServices())});p.Controls.Add(serviceGrid);p.Controls.Add(top);serviceGrid.SelectionChanged+=(_,_)=>SelectService();}
 void BuildOrders(){var p=Page("Gọi dịch vụ");var top=Bar(92);roomChoice.SelectedIndexChanged+=(_,_)=>LoadActiveRoom();top.Controls.AddRange(new Control[]{L("Phòng đang sử dụng"),roomChoice,B("Mở phòng",(_,_)=>OpenRoom()),L("Dịch vụ"),serviceChoice,L("Số lượng"),qty,B("Thêm vào bảng",(_,_)=>AddService()),B("Lưu dịch vụ",(_,_)=>SaveServiceOrders()),B("THANH TOÁN",(_,_)=>Checkout()),B("Làm mới",(_,_)=>LoadRooms()),currentBill});var split=new SplitContainer{Dock=DockStyle.Fill,Orientation=Orientation.Horizontal,SplitterDistance=360};serviceOrderGrid.ReadOnly=false;serviceOrderGrid.AllowUserToAddRows=false;serviceOrderGrid.AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill;split.Panel1.Controls.Add(serviceOrderGrid);split.Panel2.Controls.Add(orderGrid);p.Controls.Add(split);p.Controls.Add(top);}
 void BuildReports(){var p=Page("Báo cáo");var top=Bar(46);top.Controls.Add(new Label{Name="reportStats",AutoSize=true,Font=new Font("Segoe UI",14,FontStyle.Bold),ForeColor=Color.DarkGreen,Margin=new Padding(8,8,18,2)});top.Controls.Add(B("Cập nhật báo cáo",(_,_)=>LoadReports()));var split=new SplitContainer{Dock=DockStyle.Fill,Orientation=Orientation.Horizontal,SplitterDistance=420};split.Panel1.Controls.Add(reportGrid);split.Panel2.Controls.Add(detailGrid);p.Controls.Add(split);p.Controls.Add(top);reportGrid.SelectionChanged+=(_,_)=>LoadInvoiceDetails();}
 void RefreshAll(){try{LoadServices();LoadRooms();LoadReports();}catch(Exception ex){Error(ex);}}
 void LoadServices(){services=svc.Repository.Services();serviceGrid.DataSource=services;serviceChoice.DataSource=services.Copy();serviceChoice.DisplayMember="TenDV";serviceChoice.ValueMember="MaDV";}
 void LoadRooms(){var data=svc.Repository.Rooms();roomGrid.Controls.Clear();roomChoice.DataSource=data.Copy();roomChoice.DisplayMember="TenPhong";roomChoice.ValueMember="MaPhong";var open=0;foreach(DataRow row in data.Rows){bool busy=row["TrangThai"].ToString()=="Đang hát";if(busy)open++;var button=new Button{Width=220,Height=122,Margin=new Padding(12),BackColor=busy?Color.FromArgb(220,70,70):Color.FromArgb(45,165,100),ForeColor=Color.White,FlatStyle=FlatStyle.Flat,Font=new Font("Segoe UI",13,FontStyle.Bold),Text=$"{row["TenPhong"]}\n{row["LoaiPhong"]}  •  {Convert.ToDecimal(row["GiaTheoGio"]):N0} đ/giờ\n{row["TrangThai"]}"};int id=Convert.ToInt32(row["MaPhong"]);button.Click+=(_,_)=>{selectedRoom=id;roomChoice.SelectedValue=id;LoadActiveRoom();};roomGrid.Controls.Add(button);}var stats=Controls.Find("roomStats",true).FirstOrDefault() as Label;if(stats!=null)stats.Text=$"{data.Rows.Count-open} phòng trống  •  {open} phòng đang hát     |     Xanh: Trống • Đỏ: Đang hát";}
 void LoadActiveRoom(){if(roomChoice.SelectedValue is null)return;int id=int.TryParse(roomChoice.SelectedValue.ToString(),out var x)?x:0;if(id==0)return;selectedRoom=id;billId=svc.Repository.ActiveInvoice(id);currentBill.Text=billId is null?"Chưa mở phòng":"Hóa đơn #"+billId.Value;serviceTable=billId is null?new DataTable():svc.Repository.LoadServiceTable(billId.Value);serviceOrderGrid.DataSource=serviceTable;}
 void OpenRoom(){if(roomChoice.SelectedValue is null)return;try{int id=Convert.ToInt32(roomChoice.SelectedValue);billId=svc.Repository.OpenRoom(id);selectedRoom=id;LoadRooms();roomChoice.SelectedValue=id;LoadActiveRoom();MessageBox.Show($"Đã mở phòng. Hóa đơn #{billId}.");}catch(Exception ex){Error(ex);}}
 void AddService(){try{if(billId is null||serviceTable is null)throw new InvalidOperationException("Mở phòng trước khi gọi dịch vụ.");if(serviceChoice.SelectedItem is not DataRowView r)return;svc.Repository.AddService(serviceTable,billId.Value,Convert.ToInt32(r["MaDV"]),Convert.ToInt32(qty.Value),Convert.ToDecimal(r["DonGia"]));serviceOrderGrid.DataSource=serviceTable;}
 catch(Exception ex){Error(ex);}}
 void SaveServiceOrders(){if(serviceTable is null||billId is null){MessageBox.Show("Mở phòng trước khi lưu dịch vụ.");return;}try{serviceOrderGrid.EndEdit();int n=svc.Repository.SaveServiceTable(serviceTable);MessageBox.Show($"Đã đồng bộ {n} dòng bằng DataAdapter/CommandBuilder.");LoadActiveRoom();}catch(Exception ex){Error(ex);}}
 void Checkout(){if(selectedRoom is null||billId is null){MessageBox.Show("Chọn phòng đang hát.");return;}try{serviceOrderGrid.EndEdit();if(serviceTable!=null)svc.Repository.SaveServiceTable(serviceTable);svc.Repository.Checkout(selectedRoom.Value);MessageBox.Show("Thanh toán thành công; tồn kho và trạng thái phòng đã cập nhật.","Hoàn tất");serviceTable=null;billId=null;LoadRooms();LoadReports();}catch(Exception ex){Error(ex);}}
 void SelectService(){if(serviceGrid.CurrentRow?.DataBoundItem is not DataRowView r)return;serviceId=Convert.ToInt32(r["MaDV"]);serviceName.Text=r["TenDV"].ToString();servicePrice.Text=Convert.ToDecimal(r["DonGia"]).ToString("0.##");serviceStock.Text=r["TonKho"].ToString();}
 void SaveService(){try{svc.ValidateService(serviceName.Text,decimal.Parse(servicePrice.Text),int.Parse(serviceStock.Text));svc.Repository.SaveService(serviceId,serviceName.Text.Trim(),decimal.Parse(servicePrice.Text),int.Parse(serviceStock.Text));LoadServices();MessageBox.Show("Đã lưu danh mục dịch vụ.");}catch(Exception ex){Error(ex);}}
 void LoadReports(){var t=svc.Repository.Invoices();orderGrid.DataSource=t.Copy();reportGrid.DataSource=t;var stats=Controls.Find("reportStats",true).FirstOrDefault() as Label;if(stats!=null)stats.Text=$"Tổng hóa đơn: {svc.Repository.Scalar("SELECT COUNT(*) FROM HoaDon")}   •   Đã thanh toán: {svc.Repository.Scalar("SELECT COUNT(*) FROM HoaDon WHERE TrangThai=1")}   •   Phòng đang hát: {svc.Repository.Scalar("SELECT COUNT(*) FROM PhongHat WHERE TrangThai=N'Đang hát'")}";}
 void LoadInvoiceDetails(){if(reportGrid.CurrentRow?.DataBoundItem is not DataRowView r)return;try{detailGrid.DataSource=svc.Repository.RoomServiceNames(Convert.ToInt32(r["MaHD"]));}catch{}}
 void Error(Exception ex)=>MessageBox.Show(ex.Message,"Có lỗi",MessageBoxButtons.OK,MessageBoxIcon.Warning);
}
